import { test } from "node:test";
import assert from "node:assert/strict";

import { validateCreateUser } from "./validation.js";
import { lineTotal, orderTotal } from "./pricing.js";
import { loadOrders, type OrderStore } from "./repository.js";
import { resolveUserFile, BASE_DIR, MESSAGE_UNSAFE_FILE_NAME, UnsafeFileNameError } from "./files.js";

/** Names a client may legitimately request, including ones that only look like traversal. */
const VALID_FILE_NAMES = ["avatar.png", "nested/avatar.png", "..avatar.png", "100%-done.png"];

/** Names that climb out of the base directory once normalized. */
const TRAVERSAL_FILE_NAMES = [
  "../secrets.txt",
  "../../etc/passwd",
  "nested/../../escape.txt",
  "/etc/passwd",
  "",
];

/** Names that only become traversal after percent-decoding, including double encoding. */
const ENCODED_TRAVERSAL_FILE_NAMES = [
  "%2e%2e%2fsecrets.txt",
  "%2E%2E%2Fsecrets.txt",
  "..%2f..%2fetc%2fpasswd",
  "%2e%2e%00.png",
  "%252e%252e%252fsecrets.txt",
];

test("validates a valid user", () => {
  assert.deepEqual(validateCreateUser({ email: "a@b.co", name: "Ada", age: 30 }), {
    ok: true,
    errors: [],
  });
});

test("rejects a missing email", () => {
  const result = validateCreateUser({ name: "Ada" });
  assert.equal(result.ok, false);
  assert.match(result.errors.join(","), /email/);
});

test("prices taxable and non-taxable items", () => {
  assert.equal(lineTotal({ unitPrice: 10, quantity: 2, taxable: false }), 20);
  assert.equal(lineTotal({ unitPrice: 10, quantity: 2, taxable: true }), 24);
});

test("totals an order", () => {
  assert.equal(
    orderTotal([
      { unitPrice: 10, quantity: 1, taxable: false },
      { unitPrice: 5, quantity: 2, taxable: true },
    ]),
    22,
  );
});

test("loads orders in order", async () => {
  const store: OrderStore = {
    async findById(id) {
      return { id, total: 1 };
    },
  };
  const orders = await loadOrders(store, ["a", "b"]);
  assert.deepEqual(orders.map((o) => o.id), ["a", "b"]);
});

test("resolves a normal file name", () => {
  assert.equal(resolveUserFile("avatar.png"), `${BASE_DIR}/avatar.png`);
});

test("keeps the response shape for every valid file name", () => {
  for (const name of VALID_FILE_NAMES) {
    const resolved = resolveUserFile(name);
    assert.equal(typeof resolved, "string");
    assert.equal(resolved, `${BASE_DIR}/${name}`);
  }
});

test("rejects traversal file names", () => {
  for (const name of TRAVERSAL_FILE_NAMES) {
    assert.throws(() => resolveUserFile(name), UnsafeFileNameError, `expected rejection for ${name}`);
  }
});

test("rejects percent-encoded traversal file names", () => {
  for (const name of ENCODED_TRAVERSAL_FILE_NAMES) {
    assert.throws(
      () => resolveUserFile(name),
      UnsafeFileNameError,
      `expected rejection for ${name}`,
    );
  }
});

test("reports the rejection reason for unsafe names", () => {
  assert.throws(() => resolveUserFile("../secrets.txt"), {
    name: "UnsafeFileNameError",
    message: MESSAGE_UNSAFE_FILE_NAME,
  });
});
EOF

